def compute(vars):
    total = vars["v1"] + vars["v2"] + vars["v3"]
    return {
        "value": total,
        "trace": {
            "fiscal_2012_cost": vars["v1"],
            "fiscal_2013_cost": vars["v2"],
            "fiscal_2014_cost": vars["v3"],
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
